 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v != 9), None)
    # Connect consecutive markers in each row and column with color 3.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
